//! Complete rational graph families over the real or complex numbers.
//!
//! A candidate fixes some coordinates by relations `a_i(t)*x_i-b_i(t)` from
//! the original ideal, leaving the other original coordinates free. Every
//! denominator is proved nonzero on the entire original variety: the
//! independently checked ideal generated by the original basis and `a_i` is
//! the unit ideal. Exact denominator-cleared substitution then checks every
//! original equation. These two independent obligations establish both
//! directions of the parametrization; a valid generic chart alone is never
//! accepted when exceptional fibers remain.
//!
//! The result retains explicit nonzero conditions and held rational values,
//! without cancelling their denominator domains. Recognition searches all
//! pivot subsets in a deterministic order, but only uses single-coordinate
//! linear relations already present in the originals or the checked basis.
//! Unrecognized, constrained, or singular families return `NotApplicable`.
//! All work shares separate cumulative generator/verifier caps, including
//! every failed chart and denominator proof. This synchronous bounded lane
//! does not claim runtime supervision or general rational parametrization.

#![forbid(unsafe_code)]

use std::collections::BTreeMap;
use std::sync::Arc;

use fsym_budget::{Budget, BudgetError, BudgetLimits, BudgetMeter, Dimension, MeterError};
use fsym_core::{BigRational, Expr, Symbol};
use fsym_polys::{
    MultivariatePoly, TermOrder, VerifiedGroebnerBasis, bounded_polynomial_from_expr,
    checked_groebner_basis,
};
use num_traits::{One, Zero};

use crate::SolverError;

const MAX_VARIABLES: usize = 8;
const MAX_EQUATIONS: usize = 64;
const MAX_TERMS: usize = 4096;
const MAX_DEGREE: u64 = 256;
const MAX_BITS: u64 = 4096;
const MAX_OUTPUT_NODES: usize = 4096;
const MAX_COMPUTE: u64 = 200_000_000;
const MAX_MEMORY: u64 = 512 * 1024 * 1024;

type Result<T> = std::result::Result<T, SolverError>;
type Terms = BTreeMap<Vec<u32>, BigRational>;

#[derive(Debug, Clone)]
pub enum RationalGraphOutcome {
    Empty,
    Family(Box<VerifiedRationalGraph>),
    NotApplicable,
}

/// The complete family on the explicitly retained nonzero parameter domain.
/// Coordinate, numerator and denominator vectors follow the original order.
#[derive(Debug, Clone)]
pub struct VerifiedRationalGraph {
    variables: Vec<Symbol>,
    values: Vec<Expr>,
    free_variables: Vec<Symbol>,
    numerators: Vec<MultivariatePoly>,
    denominators: Vec<MultivariatePoly>,
    numerator_values: Vec<Expr>,
    denominator_values: Vec<Expr>,
    nonzero_conditions: Vec<Expr>,
    basis: VerifiedGroebnerBasis,
    nonzero_bases: Vec<VerifiedGroebnerBasis>,
}

impl VerifiedRationalGraph {
    pub fn variables(&self) -> &[Symbol] {
        &self.variables
    }

    pub fn values(&self) -> &[Expr] {
        &self.values
    }

    pub fn into_values(self) -> Vec<Expr> {
        self.values
    }

    pub fn free_variables(&self) -> &[Symbol] {
        &self.free_variables
    }

    pub fn numerators(&self) -> &[MultivariatePoly] {
        &self.numerators
    }

    pub fn denominators(&self) -> &[MultivariatePoly] {
        &self.denominators
    }

    /// Transfer already charged polynomial expression parts to a bridge.
    /// The bridge must retain the explicit conditions and reconstruct held
    /// rational operations instead of cancelling their domains.
    pub fn into_parts(self) -> (Vec<Expr>, Vec<Expr>, Vec<Expr>) {
        (
            self.numerator_values,
            self.denominator_values,
            self.nonzero_conditions,
        )
    }

    /// Each returned expression must be nonzero. The same exact expression
    /// occurs as a held reciprocal in at least one published coordinate.
    pub fn nonzero_conditions(&self) -> &[Expr] {
        &self.nonzero_conditions
    }

    pub fn basis(&self) -> &VerifiedGroebnerBasis {
        &self.basis
    }

    /// Unit-ideal receipts, in the same order as `nonzero_conditions`.
    pub fn nonzero_bases(&self) -> &[VerifiedGroebnerBasis] {
        &self.nonzero_bases
    }
}

#[derive(Clone)]
struct Candidate {
    pivots: Vec<usize>,
    relations: Vec<MultivariatePoly>,
    relation_scales: Vec<BigRational>,
    numerators: Vec<MultivariatePoly>,
    denominators: Vec<MultivariatePoly>,
    guards: Vec<MultivariatePoly>,
    nonzero_bases: Vec<VerifiedGroebnerBasis>,
}

fn refuse(message: impl std::fmt::Display) -> SolverError {
    SolverError::IncompleteSolutionSet(format!("rational graph refused: {message}"))
}

struct Capped<'a, M> {
    inner: &'a mut M,
    used: [u64; 3],
}

impl<M: BudgetMeter> BudgetMeter for Capped<'_, M> {
    fn charge(&mut self, dimension: Dimension, amount: u64) -> std::result::Result<(), MeterError> {
        self.charge_batch(&[(dimension, amount)])
    }

    fn charge_batch(
        &mut self,
        charges: &[(Dimension, u64)],
    ) -> std::result::Result<(), MeterError> {
        let mut next = self.used;
        for &(dimension, amount) in charges {
            let (index, limit) = match dimension {
                Dimension::ComputeSteps => (0, MAX_COMPUTE),
                Dimension::MemoryBytes => (1, MAX_MEMORY),
                Dimension::AllocationCount => (2, MAX_COMPUTE),
                _ => continue,
            };
            let remaining = limit.saturating_sub(next[index]);
            if amount > remaining {
                return Err(MeterError::Budget(BudgetError::Exhausted {
                    dimension,
                    requested: amount,
                    remaining,
                }));
            }
            next[index] += amount;
        }
        self.inner.charge_batch(charges)?;
        self.used = next;
        Ok(())
    }

    fn checkpoint(&mut self) -> std::result::Result<(), MeterError> {
        self.inner.checkpoint()
    }
}

fn charge(meter: &mut impl BudgetMeter, steps: usize, bytes: usize) -> Result<()> {
    meter.checkpoint().map_err(refuse)?;
    meter
        .charge_batch(&[
            (Dimension::ComputeSteps, steps.max(1) as u64),
            (Dimension::MemoryBytes, bytes.max(1) as u64),
            (Dimension::AllocationCount, 1),
        ])
        .map_err(refuse)
}

fn ring_bytes(variables: &[Symbol]) -> usize {
    variables.iter().map(|symbol| symbol.name.len() + 128).sum()
}

fn check_scalar(value: &BigRational) -> Result<()> {
    if value.numer().bits().max(value.denom().bits()) > MAX_BITS {
        return Err(refuse("coefficient exceeds 4096 bits"));
    }
    Ok(())
}

fn check_poly(
    polynomial: &MultivariatePoly,
    variables: &[Symbol],
    meter: &mut impl BudgetMeter,
) -> Result<()> {
    charge(meter, polynomial.terms().len().max(1), 1)?;
    if polynomial.generators() != variables || polynomial.terms().len() > MAX_TERMS {
        return Err(refuse("polynomial ring or term bound mismatch"));
    }
    for (powers, coefficient) in polynomial.terms() {
        charge(meter, powers.len(), 1)?;
        if powers.len() != variables.len()
            || powers.iter().map(|&power| u64::from(power)).sum::<u64>() > MAX_DEGREE
            || coefficient.is_zero()
        {
            return Err(refuse("noncanonical or oversized polynomial monomial"));
        }
        check_scalar(coefficient)?;
    }
    Ok(())
}

fn copy_poly(poly: &MultivariatePoly, meter: &mut impl BudgetMeter) -> Result<MultivariatePoly> {
    check_poly(poly, poly.generators(), meter)?;
    charge(
        meter,
        poly.terms().len(),
        ring_bytes(poly.generators()) + poly.terms().len() * 2048 + 128,
    )?;
    Ok(poly.clone())
}

fn from_terms(
    variables: &[Symbol],
    terms: Terms,
    meter: &mut impl BudgetMeter,
) -> Result<MultivariatePoly> {
    // Construction canonicalizes into a new map; count that transient map as
    // well as the entries already charged while accumulating these terms.
    charge(
        meter,
        terms.len(),
        ring_bytes(variables) + terms.len() * 128 + 128,
    )?;
    let poly = MultivariatePoly::new(variables.to_vec(), terms).map_err(refuse)?;
    check_poly(&poly, variables, meter)?;
    Ok(poly)
}

fn constant(
    variables: &[Symbol],
    value: &BigRational,
    meter: &mut impl BudgetMeter,
) -> Result<MultivariatePoly> {
    check_scalar(value)?;
    charge(meter, 1, 2048)?;
    let mut terms = Terms::new();
    if !value.is_zero() {
        terms.insert(vec![0; variables.len()], value.clone());
    }
    from_terms(variables, terms, meter)
}

fn variable(
    variables: &[Symbol],
    index: usize,
    meter: &mut impl BudgetMeter,
) -> Result<MultivariatePoly> {
    charge(meter, 1, ring_bytes(variables) + 2048)?;
    MultivariatePoly::var(variables.to_vec(), &variables[index]).map_err(refuse)
}

fn accumulate(
    terms: &mut Terms,
    powers: Vec<u32>,
    value: BigRational,
    meter: &mut impl BudgetMeter,
) -> Result<()> {
    check_scalar(&value)?;
    if powers.iter().map(|&power| u64::from(power)).sum::<u64>() > MAX_DEGREE {
        return Err(refuse("residual polynomial exceeds degree 256"));
    }
    let value = if let Some(previous) = terms.get(&powers) {
        let sum = previous.metered_add(&value, meter).map_err(refuse)?;
        check_scalar(&sum)?;
        sum
    } else {
        value
    };
    charge(meter, 1, 2048)?;
    if value.is_zero() {
        terms.remove(&powers);
    } else {
        terms.insert(powers, value);
        if terms.len() > MAX_TERMS {
            return Err(refuse("residual polynomial exceeds 4096 terms"));
        }
    }
    Ok(())
}

fn multiply(
    left: &MultivariatePoly,
    right: &MultivariatePoly,
    meter: &mut impl BudgetMeter,
) -> Result<MultivariatePoly> {
    check_poly(left, right.generators(), meter)?;
    check_poly(right, left.generators(), meter)?;
    let mut terms = Terms::new();
    for (a_powers, a) in left.terms() {
        for (b_powers, b) in right.terms() {
            charge(meter, a_powers.len(), a_powers.len() * 4 + 128)?;
            let powers: Vec<_> = a_powers.iter().zip(b_powers).map(|(a, b)| a + b).collect();
            if powers.iter().map(|&power| u64::from(power)).sum::<u64>() > MAX_DEGREE {
                return Err(refuse("residual product exceeds degree 256"));
            }
            let value = a.metered_mul(b, meter).map_err(refuse)?;
            accumulate(&mut terms, powers, value, meter)?;
        }
    }
    from_terms(left.generators(), terms, meter)
}

fn power(
    polynomial: &MultivariatePoly,
    mut exponent: u32,
    meter: &mut impl BudgetMeter,
) -> Result<MultivariatePoly> {
    let mut result = constant(polynomial.generators(), &BigRational::one(), meter)?;
    let mut factor = copy_poly(polynomial, meter)?;
    while exponent > 0 {
        if exponent % 2 == 1 {
            result = multiply(&result, &factor, meter)?;
        }
        exponent /= 2;
        if exponent > 0 {
            factor = multiply(&factor, &factor, meter)?;
        }
    }
    Ok(result)
}

fn subtract(
    left: &MultivariatePoly,
    right: &MultivariatePoly,
    meter: &mut impl BudgetMeter,
) -> Result<MultivariatePoly> {
    check_poly(left, right.generators(), meter)?;
    charge(meter, left.terms().len(), left.terms().len() * 2048)?;
    let mut terms = left.terms().clone();
    for (powers, value) in right.terms() {
        charge(meter, 1, 2048)?;
        accumulate(&mut terms, powers.clone(), -value.clone(), meter)?;
    }
    from_terms(left.generators(), terms, meter)
}

fn is_constant(poly: &MultivariatePoly) -> bool {
    poly.terms()
        .keys()
        .all(|powers| powers.iter().all(|&power| power == 0))
}

fn scale(
    polynomial: &MultivariatePoly,
    factor: &BigRational,
    meter: &mut impl BudgetMeter,
) -> Result<MultivariatePoly> {
    check_scalar(factor)?;
    let mut terms = Terms::new();
    for (powers, value) in polynomial.terms() {
        charge(meter, powers.len(), 2048)?;
        let scaled = value.metered_mul(factor, meter).map_err(refuse)?;
        accumulate(&mut terms, powers.clone(), scaled, meter)?;
    }
    from_terms(polynomial.generators(), terms, meter)
}

/// A reference substitution in Q[t], after multiplying by a sufficiently high
/// power of each coordinate denominator. No source expressions or generator
/// substitutions are reused here.
fn residuals_zero(
    inputs: &[MultivariatePoly],
    candidate: &Candidate,
    meter: &mut impl BudgetMeter,
) -> Result<bool> {
    for input in inputs {
        let variables = input.generators();
        charge(
            meter,
            variables.len() * input.terms().len(),
            variables.len() * 4,
        )?;
        let degrees: Vec<_> = (0..variables.len())
            .map(|index| input.degree_in(index))
            .collect();
        let mut sum = Terms::new();
        for (powers, coefficient) in input.terms() {
            let mut term = constant(variables, coefficient, meter)?;
            for (index, &exponent) in powers.iter().enumerate() {
                let numerator = power(&candidate.numerators[index], exponent, meter)?;
                let denominator = power(
                    &candidate.denominators[index],
                    degrees[index] - exponent,
                    meter,
                )?;
                term = multiply(&term, &numerator, meter)?;
                term = multiply(&term, &denominator, meter)?;
            }
            for (powers, value) in term.terms() {
                charge(meter, 1, 2048)?;
                accumulate(&mut sum, powers.clone(), value.clone(), meter)?;
            }
        }
        if !sum.is_empty() {
            return Ok(false);
        }
    }
    Ok(true)
}

/// Generator-only relation extraction. The reference checker reconstructs
/// `denominator*x_i - numerator` independently and compares the entire result.
fn extract_relation(
    poly: &MultivariatePoly,
    pivot: usize,
    mask: usize,
    meter: &mut impl BudgetMeter,
) -> Result<Option<(MultivariatePoly, MultivariatePoly, BigRational)>> {
    let variables = poly.generators();
    charge(meter, poly.terms().len() * variables.len(), 1)?;
    if !poly.terms().keys().any(|powers| powers[pivot] != 0)
        || poly.terms().keys().any(|powers| {
            powers[pivot] > 1
                || powers
                    .iter()
                    .enumerate()
                    .any(|(index, &power)| index != pivot && mask & (1 << index) != 0 && power != 0)
        })
    {
        return Ok(None);
    }
    let mut numerator = Terms::new();
    let mut denominator = Terms::new();
    for (powers, value) in poly.terms() {
        charge(meter, 1, 4096)?;
        let mut exponent = powers.clone();
        if exponent[pivot] == 1 {
            exponent[pivot] = 0;
            denominator.insert(exponent, value.clone());
        } else {
            numerator.insert(exponent, -value.clone());
        }
    }
    let numerator = from_terms(variables, numerator, meter)?;
    let denominator = from_terms(variables, denominator, meter)?;
    let (_, leading) = denominator
        .leading_term(TermOrder::Lex)
        .ok_or_else(|| refuse("recognized linear relation lost its denominator"))?;
    let factor = BigRational::one()
        .metered_div(leading, meter)
        .map_err(refuse)?;
    check_scalar(&factor)?;
    Ok(Some((
        scale(&numerator, &factor, meter)?,
        scale(&denominator, &factor, meter)?,
        factor,
    )))
}

fn candidate_for_mask(
    basis: &VerifiedGroebnerBasis,
    mask: usize,
    meter: &mut impl BudgetMeter,
) -> Result<Option<Candidate>> {
    let variables = basis.input_basis()[0].generators();
    charge(meter, variables.len(), variables.len() * 768)?;
    let mut candidate = Candidate {
        pivots: Vec::new(),
        relations: Vec::new(),
        relation_scales: Vec::new(),
        numerators: Vec::with_capacity(variables.len()),
        denominators: Vec::with_capacity(variables.len()),
        guards: Vec::new(),
        nonzero_bases: Vec::new(),
    };
    for index in 0..variables.len() {
        if mask & (1 << index) == 0 {
            candidate
                .numerators
                .push(variable(variables, index, meter)?);
            candidate
                .denominators
                .push(constant(variables, &BigRational::one(), meter)?);
            continue;
        }
        let mut chosen = None;
        for relation in basis.basis().iter().chain(basis.input_basis()) {
            if let Some((numerator, denominator, factor)) =
                extract_relation(relation, index, mask, meter)?
            {
                let key = (
                    !is_constant(&denominator),
                    numerator.terms().len() + denominator.terms().len(),
                );
                if chosen.as_ref().is_none_or(|(old, _, _, _, _)| key < *old) {
                    chosen = Some((
                        key,
                        copy_poly(relation, meter)?,
                        numerator,
                        denominator,
                        factor,
                    ));
                }
            }
        }
        let Some((_, relation, numerator, denominator, factor)) = chosen else {
            return Ok(None);
        };
        if !is_constant(&denominator) && !candidate.guards.contains(&denominator) {
            candidate.guards.push(copy_poly(&denominator, meter)?);
        }
        candidate.pivots.push(index);
        candidate.relations.push(relation);
        candidate.relation_scales.push(factor);
        candidate.numerators.push(numerator);
        candidate.denominators.push(denominator);
    }
    Ok(Some(candidate))
}

/// Reference completeness boundary: it accepts previously checked ideal
/// receipts, but invokes no Groebner generator or relation-selection routine.
fn verify_candidate(
    basis: &VerifiedGroebnerBasis,
    candidate: &Candidate,
    meter: &mut impl BudgetMeter,
) -> Result<()> {
    let variables = basis
        .input_basis()
        .first()
        .ok_or_else(|| refuse("missing original ambient ring"))?
        .generators();
    let width = variables.len();
    charge(meter, width, 1)?;
    if width == 0
        || width > MAX_VARIABLES
        || candidate.pivots.len() != candidate.relations.len()
        || candidate.pivots.len() != candidate.relation_scales.len()
        || candidate.numerators.len() != width
        || candidate.denominators.len() != width
        || candidate.guards.len() != candidate.nonzero_bases.len()
        || candidate
            .pivots
            .iter()
            .enumerate()
            .any(|(row, &pivot)| pivot >= width || candidate.pivots[..row].contains(&pivot))
    {
        return Err(refuse(
            "candidate dimensions or pivot identities do not bind",
        ));
    }
    for index in 0..width {
        let numerator = &candidate.numerators[index];
        let denominator = &candidate.denominators[index];
        check_poly(numerator, variables, meter)?;
        check_poly(denominator, variables, meter)?;
        if denominator.is_zero() {
            return Err(refuse("zero coordinate denominator"));
        }
        if !denominator
            .leading_term(TermOrder::Lex)
            .is_some_and(|(_, coefficient)| coefficient.is_one())
        {
            return Err(refuse("coordinate denominator is not canonically monic"));
        }
        let unit = variable(variables, index, meter)?;
        if let Some(row) = candidate.pivots.iter().position(|&pivot| pivot == index) {
            if [numerator, denominator].iter().any(|poly| {
                poly.terms()
                    .keys()
                    .any(|powers| candidate.pivots.iter().any(|&pivot| powers[pivot] != 0))
            }) {
                return Err(refuse("rational coordinates still depend on a pivot"));
            }
            let relation = &candidate.relations[row];
            let factor = &candidate.relation_scales[row];
            check_scalar(factor)?;
            if factor.is_zero() {
                return Err(refuse("zero relation scale cannot determine a pivot"));
            }
            if !basis.input_basis().contains(relation) && !basis.basis().contains(relation) {
                return Err(refuse(
                    "a pivot relation is not bound to the original ideal",
                ));
            }
            let product = multiply(denominator, &unit, meter)?;
            let scaled_relation = scale(relation, factor, meter)?;
            if subtract(&product, numerator, meter)? != scaled_relation {
                return Err(refuse("a rational coordinate changed its ideal relation"));
            }
        } else if *numerator != unit || !denominator.is_one() {
            return Err(refuse("a free coordinate was changed or captured"));
        }
    }
    for (index, guard) in candidate.guards.iter().enumerate() {
        check_poly(guard, variables, meter)?;
        if guard.is_zero()
            || is_constant(guard)
            || candidate.guards[..index].contains(guard)
            || !candidate.denominators.contains(guard)
        {
            return Err(refuse("an extra, duplicate or missing domain condition"));
        }
        let proof = &candidate.nonzero_bases[index];
        let inputs = proof.input_basis();
        if inputs.len() != basis.basis().len() + 1
            || inputs[..basis.basis().len()] != *basis.basis()
            || inputs.last() != Some(guard)
            || !proof.basis().iter().any(MultivariatePoly::is_one)
        {
            return Err(refuse(
                "denominator nonvanishing is not proved for this original ideal",
            ));
        }
    }
    if candidate
        .denominators
        .iter()
        .any(|denominator| !is_constant(denominator) && !candidate.guards.contains(denominator))
    {
        return Err(refuse("a denominator lost its original-domain obligation"));
    }
    if !residuals_zero(basis.input_basis(), candidate, meter)? {
        return Err(refuse(
            "a lifted rational family fails an original equation",
        ));
    }
    meter.checkpoint().map_err(refuse)
}

fn expression(
    poly: &MultivariatePoly,
    meter: &mut impl BudgetMeter,
    nodes: &mut usize,
) -> Result<Expr> {
    let projected = 1 + poly
        .terms()
        .keys()
        .map(|powers| 2 + powers.iter().filter(|&&power| power != 0).count() * 4)
        .sum::<usize>();
    *nodes = nodes
        .checked_add(projected)
        .filter(|&value| value <= MAX_OUTPUT_NODES)
        .ok_or_else(|| refuse("rational graph exceeds 4096 projected output nodes"))?;
    charge(
        meter,
        projected,
        projected * (2048 + ring_bytes(poly.generators())),
    )?;
    poly.to_expr().map_err(refuse)
}

struct Lifted {
    values: Vec<Expr>,
    conditions: Vec<Expr>,
    numerators: Vec<Expr>,
    denominators: Vec<Expr>,
}

fn lift(candidate: &Candidate, meter: &mut impl BudgetMeter) -> Result<Lifted> {
    let mut nodes = candidate.numerators.len() * 4;
    charge(meter, nodes, nodes * 128)?;
    let mut values = Vec::with_capacity(candidate.numerators.len());
    let mut numerators = Vec::with_capacity(candidate.numerators.len());
    let mut denominators = Vec::with_capacity(candidate.numerators.len());
    for (numerator, denominator) in candidate.numerators.iter().zip(&candidate.denominators) {
        numerators.push(expression(numerator, meter, &mut nodes)?);
        denominators.push(expression(denominator, meter, &mut nodes)?);
        let numerator = expression(numerator, meter, &mut nodes)?;
        let value = if denominator.is_one() {
            numerator
        } else {
            let denominator = expression(denominator, meter, &mut nodes)?;
            Expr::Mul(vec![
                numerator,
                Expr::Pow(Arc::new(denominator), Arc::new(Expr::from_i64(-1))),
            ])
        };
        values.push(value);
    }
    let conditions = candidate
        .guards
        .iter()
        .map(|poly| expression(poly, meter, &mut nodes))
        .collect::<Result<Vec<_>>>()?;
    Ok(Lifted {
        values,
        conditions,
        numerators,
        denominators,
    })
}

fn verify_lift(
    candidate: &Candidate,
    values: &[Expr],
    conditions: &[Expr],
    meter: &mut impl BudgetMeter,
) -> Result<()> {
    if values.len() != candidate.numerators.len() || conditions.len() != candidate.guards.len() {
        return Err(refuse("lifted family dimensions changed"));
    }
    let variables = candidate.numerators[0].generators();
    for ((value, numerator), denominator) in values
        .iter()
        .zip(&candidate.numerators)
        .zip(&candidate.denominators)
    {
        let (top, bottom) = if denominator.is_one() {
            (value, None)
        } else if let Expr::Mul(factors) = value {
            match factors.as_slice() {
                [top, Expr::Pow(bottom, exponent)] if **exponent == Expr::from_i64(-1) => {
                    (top, Some(bottom.as_ref()))
                }
                _ => return Err(refuse("lifted coordinate erased its held denominator")),
            }
        } else {
            return Err(refuse("lifted coordinate erased its rational domain"));
        };
        if bounded_polynomial_from_expr(top, variables, meter).map_err(refuse)? != *numerator {
            return Err(refuse("lifted numerator changed"));
        }
        if let Some(bottom) = bottom
            && bounded_polynomial_from_expr(bottom, variables, meter).map_err(refuse)?
                != *denominator
        {
            return Err(refuse("lifted denominator changed"));
        }
    }
    for (condition, guard) in conditions.iter().zip(&candidate.guards) {
        if bounded_polynomial_from_expr(condition, variables, meter).map_err(refuse)? != *guard
            || !values.iter().any(|value| matches!(value,
                Expr::Mul(factors) if matches!(factors.as_slice(),
                    [_, Expr::Pow(bottom, exponent)] if bottom.as_ref() == condition && **exponent == Expr::from_i64(-1))))
        {
            return Err(refuse("a nonzero condition is absent from the held coordinate domains"));
        }
    }
    meter.checkpoint().map_err(refuse)
}

pub fn metered_rational_graph_system(
    equations: &[Expr],
    variables: &[Symbol],
    generator_meter: &mut impl BudgetMeter,
    verifier_meter: &mut impl BudgetMeter,
) -> Result<RationalGraphOutcome> {
    let mut generator = Capped {
        inner: generator_meter,
        used: [0; 3],
    };
    let mut verifier = Capped {
        inner: verifier_meter,
        used: [0; 3],
    };
    charge(&mut generator, 1, 1)?;
    if variables.is_empty() || variables.len() > MAX_VARIABLES || equations.len() > MAX_EQUATIONS {
        return Err(SolverError::InvalidSystem(
            "rational graphs require 1..8 variables and at most 64 equations".into(),
        ));
    }
    let zero = bounded_polynomial_from_expr(&Expr::from_i64(0), variables, &mut generator)
        .map_err(|error| SolverError::InvalidSystem(error.to_string()))?;
    charge(
        &mut generator,
        equations.len(),
        equations.len().max(1) * 128,
    )?;
    let mut inputs = Vec::with_capacity(equations.len().max(1));
    for equation in equations {
        inputs.push(
            bounded_polynomial_from_expr(equation, variables, &mut generator)
                .map_err(|error| SolverError::InvalidSystem(error.to_string()))?,
        );
    }
    if inputs.is_empty() {
        inputs.push(zero);
    }
    let basis = checked_groebner_basis(&inputs, TermOrder::Lex, &mut generator, &mut verifier)
        .map_err(refuse)?;
    if basis.basis().iter().any(MultivariatePoly::is_one) {
        generator.checkpoint().map_err(refuse)?;
        verifier.checkpoint().map_err(refuse)?;
        return Ok(RationalGraphOutcome::Empty);
    }
    let count = 1usize << variables.len();
    charge(&mut generator, count * variables.len(), count * 8)?;
    let mut masks: Vec<_> = (0..count).collect();
    masks.sort_by_key(|&mask| (variables.len() - mask.count_ones() as usize, mask));
    for mask in masks {
        let Some(mut candidate) = candidate_for_mask(&basis, mask, &mut generator)? else {
            continue;
        };
        if !residuals_zero(basis.input_basis(), &candidate, &mut verifier)? {
            continue;
        }
        let mut nonvanishing = true;
        for guard in &candidate.guards {
            if basis.basis().len() >= MAX_EQUATIONS {
                return Err(refuse("denominator ideal exceeds 64 equations"));
            }
            charge(
                &mut generator,
                basis.basis().len() + 1,
                (basis.basis().len() + 1) * 128,
            )?;
            let mut augmented = basis
                .basis()
                .iter()
                .map(|poly| copy_poly(poly, &mut generator))
                .collect::<Result<Vec<_>>>()?;
            augmented.push(copy_poly(guard, &mut generator)?);
            let proof =
                checked_groebner_basis(&augmented, TermOrder::Lex, &mut generator, &mut verifier)
                    .map_err(refuse)?;
            if !proof.basis().iter().any(MultivariatePoly::is_one) {
                nonvanishing = false;
                break;
            }
            candidate.nonzero_bases.push(proof);
        }
        if !nonvanishing {
            continue;
        }
        verify_candidate(&basis, &candidate, &mut verifier)?;
        let lifted = lift(&candidate, &mut generator)?;
        verify_lift(
            &candidate,
            &lifted.values,
            &lifted.conditions,
            &mut verifier,
        )?;
        for ((numerator, denominator), (expected_numerator, expected_denominator)) in lifted
            .numerators
            .iter()
            .zip(&lifted.denominators)
            .zip(candidate.numerators.iter().zip(&candidate.denominators))
        {
            if bounded_polynomial_from_expr(numerator, variables, &mut verifier).map_err(refuse)?
                != *expected_numerator
                || bounded_polynomial_from_expr(denominator, variables, &mut verifier)
                    .map_err(refuse)?
                    != *expected_denominator
            {
                return Err(refuse(
                    "bridge polynomial parts changed their accepted coordinates",
                ));
            }
        }
        charge(
            &mut generator,
            variables.len(),
            ring_bytes(variables) * 2 + std::mem::size_of::<VerifiedRationalGraph>(),
        )?;
        let free_variables = variables
            .iter()
            .enumerate()
            .filter(|(index, _)| !candidate.pivots.contains(index))
            .map(|(_, variable)| variable.clone())
            .collect();
        let result = Box::new(VerifiedRationalGraph {
            variables: variables.to_vec(),
            values: lifted.values,
            free_variables,
            numerators: candidate.numerators,
            denominators: candidate.denominators,
            numerator_values: lifted.numerators,
            denominator_values: lifted.denominators,
            nonzero_conditions: lifted.conditions,
            basis,
            nonzero_bases: candidate.nonzero_bases,
        });
        generator.checkpoint().map_err(refuse)?;
        verifier.checkpoint().map_err(refuse)?;
        return Ok(RationalGraphOutcome::Family(result));
    }
    generator.checkpoint().map_err(refuse)?;
    verifier.checkpoint().map_err(refuse)?;
    Ok(RationalGraphOutcome::NotApplicable)
}

pub fn rational_graph_system(
    equations: &[Expr],
    variables: &[Symbol],
) -> Result<RationalGraphOutcome> {
    metered_rational_graph_system(
        equations,
        variables,
        &mut Budget::new(BudgetLimits::uniform(MAX_MEMORY, 0)),
        &mut Budget::new(BudgetLimits::uniform(MAX_MEMORY, 0)),
    )
}

#[cfg(test)]
mod reference_checks {
    use super::*;
    use fsym_budget::Unbounded;
    use fsym_core::{SymbolIdentity, parse};

    fn checked(sources: &[&str], variables: &[Symbol]) -> VerifiedGroebnerBasis {
        let input: Vec<_> = sources
            .iter()
            .map(|source| {
                bounded_polynomial_from_expr(&parse(source).unwrap(), variables, &mut Unbounded)
                    .unwrap()
            })
            .collect();
        checked_groebner_basis(&input, TermOrder::Lex, &mut Unbounded, &mut Unbounded).unwrap()
    }

    fn hyperbola() -> (VerifiedGroebnerBasis, Candidate) {
        let variables = vec![Symbol::new("x"), Symbol::new("y")];
        let basis = checked(&["x*y-1"], &variables);
        let mut candidate = candidate_for_mask(&basis, 1, &mut Unbounded)
            .unwrap()
            .unwrap();
        let mut augmented = basis.basis().to_vec();
        augmented.push(candidate.guards[0].clone());
        candidate.nonzero_bases.push(
            checked_groebner_basis(&augmented, TermOrder::Lex, &mut Unbounded, &mut Unbounded)
                .unwrap(),
        );
        verify_candidate(&basis, &candidate, &mut Unbounded).unwrap();
        (basis, candidate)
    }

    #[test]
    fn coordinate_and_typed_binding_mutations_do_not_inherit_the_ideal_receipt() {
        let (basis, candidate) = hyperbola();
        let variables = basis.input_basis()[0].generators();
        let polynomial = |source: &str| {
            bounded_polynomial_from_expr(&parse(source).unwrap(), variables, &mut Unbounded)
                .unwrap()
        };
        let mut mutants = Vec::new();
        let mut bad = candidate.clone();
        bad.numerators[0] = polynomial("2");
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.numerators[1] = polynomial("y+1");
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.denominators[0] = polynomial("y*y");
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.denominators[0] = polynomial("0");
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.relations[0] = polynomial("x*y-2");
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.relation_scales[0] = BigRational::zero();
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.relation_scales[0] = BigRational::from(2_i64);
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.pivots[0] = 1;
        mutants.push(bad);
        let mut bad = candidate.clone();
        bad.numerators.pop();
        mutants.push(bad);
        let mut bad = candidate.clone();
        let captured =
            Symbol::with_identity("y", SymbolIdentity::from_assumptions_digest([19; 32]));
        bad.numerators[1] =
            MultivariatePoly::var(vec![variables[0].clone(), captured.clone()], &captured).unwrap();
        mutants.push(bad);
        for bad in mutants {
            assert!(verify_candidate(&basis, &bad, &mut Unbounded).is_err());
        }
    }

    #[test]
    fn wrong_or_missing_exceptional_fiber_proofs_are_rejected() {
        let (basis, candidate) = hyperbola();
        let variables = basis.input_basis()[0].generators();
        let mut bad = candidate.clone();
        bad.guards.clear();
        bad.nonzero_bases.clear();
        assert!(verify_candidate(&basis, &bad, &mut Unbounded).is_err());
        let mut bad = candidate.clone();
        bad.guards.push(bad.guards[0].clone());
        bad.nonzero_bases.push(bad.nonzero_bases[0].clone());
        assert!(verify_candidate(&basis, &bad, &mut Unbounded).is_err());
        let mut bad = candidate.clone();
        bad.nonzero_bases[0] = checked(&["x*y-2", "y"], variables);
        assert!(verify_candidate(&basis, &bad, &mut Unbounded).is_err());
        let mut bad = candidate.clone();
        bad.nonzero_bases[0] = checked(&["x*y-1", "y-1"], variables);
        assert!(verify_candidate(&basis, &bad, &mut Unbounded).is_err());

        // The generic chart x=0 for x*y=0 has a vanishing residual, yet it
        // misses the entire y=0 component and must fail the unit-ideal check.
        let singular = checked(&["x*y"], variables);
        let mut chart = candidate_for_mask(&singular, 1, &mut Unbounded)
            .unwrap()
            .unwrap();
        chart.nonzero_bases.push(checked(&["x*y", "y"], variables));
        assert!(residuals_zero(singular.input_basis(), &chart, &mut Unbounded).unwrap());
        assert!(verify_candidate(&singular, &chart, &mut Unbounded).is_err());
    }

    #[test]
    fn independent_original_residuals_reject_a_free_parameter_constraint() {
        let variables = vec![Symbol::new("x"), Symbol::new("y"), Symbol::new("z")];
        let basis = checked(&["x*y-1", "z*z-2"], &variables);
        let mut candidate = candidate_for_mask(&basis, 1, &mut Unbounded)
            .unwrap()
            .unwrap();
        let mut augmented = basis.basis().to_vec();
        augmented.push(candidate.guards[0].clone());
        candidate.nonzero_bases.push(
            checked_groebner_basis(&augmented, TermOrder::Lex, &mut Unbounded, &mut Unbounded)
                .unwrap(),
        );
        assert!(!residuals_zero(basis.input_basis(), &candidate, &mut Unbounded).unwrap());
        assert!(verify_candidate(&basis, &candidate, &mut Unbounded).is_err());
    }

    #[test]
    fn lifting_cannot_cancel_or_replace_an_accepted_domain_guard() {
        let (_, candidate) = hyperbola();
        let good = lift(&candidate, &mut Unbounded).unwrap();
        verify_lift(&candidate, &good.values, &good.conditions, &mut Unbounded).unwrap();
        let mut values = good.values.clone();
        values[0] = Expr::from_i64(1);
        assert!(verify_lift(&candidate, &values, &good.conditions, &mut Unbounded).is_err());
        let mut values = good.values.clone();
        values[0] = Expr::Mul(vec![
            Expr::from_i64(1),
            Expr::Pow(Arc::new(parse("y").unwrap()), Arc::new(Expr::from_i64(0))),
        ]);
        assert!(verify_lift(&candidate, &values, &good.conditions, &mut Unbounded).is_err());
        let mut conditions = good.conditions.clone();
        conditions[0] = parse("y+1").unwrap();
        assert!(verify_lift(&candidate, &good.values, &conditions, &mut Unbounded).is_err());
        assert!(verify_lift(&candidate, &good.values, &[], &mut Unbounded).is_err());
    }
}
